<?php
declare(strict_types=1);
require_once __DIR__ . '/access.php';
$clientId = (int) ($_GET['client_id'] ?? 0);
if ($clientId <= 0 && ($_SESSION['user']['role'] ?? '') === 'employee') { header('Location: employee_clients.php'); exit; }
require_client_access($clientId);
$role = $_SESSION['user']['role'] ?? '';
if ($role === 'employee') { require_permission('view_clients'); require_once __DIR__ . '/employee_ui.php'; }
$stmt = db()->prepare('SELECT id, name, industry FROM clients WHERE id = ? AND active = 1'); $stmt->execute([$clientId]); $client = $stmt->fetch();
if (!$client) { http_response_code(404); exit('Client not found.'); }
$stmt = db()->prepare('SELECT field_name, field_value FROM client_details WHERE client_id = ? ORDER BY field_name'); $stmt->execute([$clientId]); $details = $stmt->fetchAll();
$stmt = db()->prepare('SELECT type, file_path, uploaded_at FROM assets WHERE client_id = ? ORDER BY uploaded_at DESC'); $stmt->execute([$clientId]); $assets = $stmt->fetchAll();
$isClient = $role === 'client';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $isClient ? 'My Profile' : 'Client Profile' ?></title><link rel="stylesheet" href="assets/css/saas.css"><style>.profile-card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:24px;box-shadow:0 4px 20px rgba(15,23,42,.05)}.brief-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.brief-item{background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:16px;min-height:105px}.brief-label{font-size:12px;text-transform:uppercase;letter-spacing:.04em;font-weight:700;color:#64748b;margin-bottom:8px}.brief-value{color:#1e293b;line-height:1.6;white-space:normal}.asset-item{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid #e2e8f0}.asset-item:last-child{border-bottom:0}@media(max-width:768px){.brief-grid{grid-template-columns:1fr}.profile-card{padding:18px}}</style><script src="assets/js/session-timeout.js" defer></script></head><body class="<?= $isClient ? 'saas-body' : 'bg-light' ?>"><?php if ($isClient): ?><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><div class="nav-label">Workspace</div><a class="saas-nav" href="client_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav" href="client_content_plan.php">◷ <span>Content plan</span></a><a class="saas-nav" href="content_archive.php">▤ <span>Archive</span></a><a class="saas-nav active" href="view_client_profile.php?client_id=<?= $clientId ?>">♙ <span>My profile</span></a><a class="saas-nav" href="my_invoices.php">▧ <span>Invoices</span></a><div class="nav-label">Account</div><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><?php else: ?><main class="container py-4"><?php endif; ?><header class="saas-topbar mb-4"><div><h1 class="saas-title"><?= $isClient ? 'My profile' : e($client['name']) ?></h1><div class="saas-subtitle"><?= e($client['industry'] ?? '') ?> · Profile and submitted brief</div></div><div><?php if ($isClient): ?><a class="btn-indigo" href="client_intake_form.php?client_id=<?= $clientId ?>">Edit Profile</a><?php elseif ($role === 'admin'): ?><a class="btn btn-primary" href="client_intake_form.php?client_id=<?= $clientId ?>">Edit brief</a><?php endif; ?></div></header><div class="row g-4"><div class="col-lg-8"><section class="profile-card"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h4 mb-1">Client brief</h2><p class="text-muted mb-0">Business and content information</p></div><span class="badge rounded-pill text-bg-light"><?= count($details) ?> fields</span></div><?php if (!$details): ?><div class="empty-state">No brief details submitted yet.</div><?php else: ?><div class="brief-grid"><?php foreach ($details as $detail): ?><article class="brief-item"><div class="brief-label"><?= e(ucwords(str_replace('_', ' ', $detail['field_name']))) ?></div><div class="brief-value"><?= nl2br(e($detail['field_value'] ?? '')) ?></div></article><?php endforeach; ?></div><?php endif; ?></section></div><div class="col-lg-4"><section class="profile-card"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h4 mb-1">Assets</h2><p class="text-muted mb-0">Shared brand files</p></div><span class="badge rounded-pill text-bg-light"><?= count($assets) ?></span></div><?php if (!$assets): ?><div class="empty-state">No assets uploaded.</div><?php else: foreach ($assets as $asset): ?><div class="asset-item"><div><a href="<?= e($asset['file_path']) ?>" target="_blank" rel="noopener"><?= e(ucfirst($asset['type'])) ?> file</a><br><small class="text-muted"><?= e($asset['uploaded_at']) ?></small></div><span class="text-muted">↗</span></div><?php endforeach; endif; ?></section></div></div><?php if ($isClient): ?></main></div><?php else: ?></main><?php endif; ?></body></html>
